    dialog.querySelector('#pubInspector').closest('section').insertAdjacentHTML('beforebegin',`<section><h3>网格行列标题</h3><label class="field">列标题（每行一个）<textarea id="pubColumnTitles" rows="3" maxlength="2000" placeholder="如：冠状面&#10;矢状面&#10;水平面"></textarea></label><label class="field">行标题（每行一个）<textarea id="pubRowTitles" rows="3" maxlength="2000" placeholder="如：Control&#10;Treatment"></textarea></label><p class="value-rule">修改行列标题会按当前网格列数重排全部面板，并预留标题空间。手工移动后请检查标题对应关系。</p></section>`);
